"""Record writers for multiple output targets."""

from __future__ import annotations

import json
import os
import sqlite3
from abc import ABC, abstractmethod
from typing import Any
from src.models import Record, BatchResult


class Writer(ABC):
    @abstractmethod
    def write_record(self, record: Record) -> None:
        pass

    @abstractmethod
    def flush(self) -> None:
        pass

    @abstractmethod
    def close(self) -> None:
        pass


class JsonWriter(Writer):
    def __init__(self, out_path: str) -> None:
        self.out_path = out_path
        self._buffer: list[Record] = []

    def write_record(self, record: Record) -> None:
        self._buffer.append(record)
        if len(self._buffer) >= 1000:
            self.flush()

    def flush(self) -> None:
        with open(self.out_path, 'a', encoding='utf-8') as f:
            for rec in self._buffer:
                f.write(json.dumps(rec.to_dict()) + '\n')
        self._buffer.clear()

    def close(self) -> None:
        self.flush()


def _adapt_record(rec: Record) -> str:
    return json.dumps(rec.to_dict())


sqlite3.register_adapter(Record, _adapt_record)


class SqliteWriter(Writer):
    def __init__(self, db_path: str, table: str = "records") -> None:
        self.db_path = db_path
        self.table = table
        self._conn = sqlite3.connect(db_path)
        self._conn.row_factory = sqlite3.Row
        self._create_table()

    def _create_table(self) -> None:
        schema = f"""
        CREATE TABLE IF NOT EXISTS {self.table} (
            record_id TEXT PRIMARY KEY,
            source TEXT,
            data TEXT,
            timestamp REAL,
            tags TEXT,
            metadata TEXT
        )
        """
        self._conn.execute(schema)
        self._conn.commit()

    def write_record(self, record: Record) -> None:
        sql = f"""
        INSERT OR REPLACE INTO {self.table}
        (record_id, source, data, timestamp, tags, metadata)
        VALUES (?,?,?,?,?,?)
        """
        self._conn.execute(
            sql,
            (
                record.record_id,
                record.source,
                json.dumps(record.data),
                record.timestamp,
                json.dumps(record.tags),
                json.dumps(record.metadata),
            ),
        )

    def flush(self) -> None:
        self._conn.commit()

    def close(self) -> None:
        self.flush()
        self._conn.close()


writers: dict[str, type[Writer]] = {
    "json": JsonWriter,
    "sqlite": SqliteWriter,
}


def create_writer(kind: str, **config: Any) -> Writer:
    cls = writers.get(kind)
    if not cls:
        raise ValueError(f"Unknown writer kind: {kind}")
    return cls(**config)


def write_records(records: list[Record], writer: Writer, metrics: Any = None) -> BatchResult:
    batch = BatchResult()
    start = time.time()
    try:
        for rec in records:
            writer.write_record(rec)
            batch.add_success()
            if metrics:
                metrics.counter("records_written").inc()
    except Exception as e:
        batch.add_failure(str(e))
        if metrics:
            metrics.counter("write_failures").inc()
    batch.duration_ms = (time.time() - start) * 1000
    writer.flush()
    return batch
