"""Job scheduler for periodic ingestion."""

from __future__ import annotations

import time
import threading
from typing import Callable, Any
from src.models import BatchResult


class Job:
    def __init__(self, name: str, interval: float, func: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
        self.name = name
        self.interval = interval
        self.func = func
        self.args = args
        self.kwargs = kwargs
        self.last_run: float | None = None

    def is_due(self) -> bool:
        if self.last_run is None:
            return True
        return time.time() - self.last_run >= self.interval

    def execute(self) -> Any:
        self.last_run = time.time()
        return self.func(*self.args, **self.kwargs)

    def status(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "interval": self.interval,
            "last_run": self.last_run,
        }


class Scheduler:
    def __init__(self) -> None:
        self.jobs: dict[str, Job] = {}
        self._thread: threading.Thread | None = None
        self._stop_event = threading.Event()

    def add_job(self, name: str, interval: float, func: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
        self.jobs[name] = Job(name, interval, func, *args, **kwargs)

    def remove_job(self, name: str) -> None:
        self.jobs.pop(name, None)

    def list_jobs(self) -> list[dict[str, Any]]:
        return [job.status() for job in self.jobs.values()]

    def run_pending(self) -> None:
        for job in self.jobs.values():
            if job.is_due():
                try:
                    job.execute()
                except Exception as e:
                    print(f"Job {job.name} failed: {e}")

    def run_loop(self) -> None:
        while not self._stop_event.is_set():
            self.run_pending()
            time.sleep(1)

    def start(self) -> None:
        if self._thread is not None and self._thread.is_alive():
            return
        self._stop_event.clear()
        self._thread = threading.Thread(target=self.run_loop, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop_event.set()
        if self._thread:
            self._thread.join(timeout=1)
        self._thread = None


_scheduler: Scheduler | None = None


def get_scheduler() -> Scheduler:
    global _scheduler
    if _scheduler is None:
        _scheduler = Scheduler()
    return _scheduler


def add_job(name: str, interval: float, func: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
    sched = get_scheduler()
    sched.add_job(name, interval, func, *args, **kwargs)


def list_jobs() -> list[dict[str, Any]]:
    sched = get_scheduler()
    return sched.list_jobs()


def run_pending() -> None:
    sched = get_scheduler()
    sched.run_pending()
