"""Record validation and schema inference."""

from __future__ import annotations

import os
import json
from typing import Any, TypeVar, Callable, cast
from src.models import Record

T = TypeVar('T')


def _resolve_refs(schema: dict[str, Any], base_path: str) -> dict[str, Any]:
    ref = schema.get("$ref")
    if ref and isinstance(ref, str):
        if ref.startswith("file://"):
            ref_path = ref[7:]
            if not os.path.isabs(ref_path):
                ref_path = os.path.join(base_path, ref_path)
            with open(ref_path, 'r', encoding='utf-8') as f:
                return cast(dict[str, Any], json.load(f))
    return schema


def _check_numeric(val: Any) -> bool:
    try:
        float(val)
        return True
    except Exception:
        return False


Validator = Callable[[Record], bool]


def _always_valid(record: Record) -> bool:
    return True


def validate_against_schema(record: Record, schema: dict[str, Any]) -> bool:
    # simple property checks: if schema has 'required' or 'properties' at top-level
    required = schema.get("required", [])
    if isinstance(required, list):
        for prop in required:
            if prop not in record.data:
                return False
    props = schema.get("properties", {})
    if isinstance(props, dict):
        for prop_name, prop_schema in props.items():
            if prop_name not in record.data:
                continue
            value = record.data[prop_name]
            if "type" in prop_schema:
                expected = prop_schema["type"]
                if expected == "number" and not _check_numeric(value):
                    return False
                if expected == "string" and not isinstance(value, str):
                    return False
    return True


class SchemaValidator:
    def __init__(self, schema: dict[str, Any] | str | None = None) -> None:
        self.schema: dict[str, Any] | None = None
        if isinstance(schema, str):
            base = os.path.dirname(schema)
            with open(schema, 'r', encoding='utf-8') as f:
                self.schema = _resolve_refs(json.load(f), base)
        else:
            self.schema = schema

    def __call__(self, record: Record) -> bool:
        if not self.schema:
            return True
        try:
            return validate_against_schema(record, self.schema)
        except Exception:
            return False


def get_common_schema(records: list[Record]) -> dict[str, Any]:
    schema: dict[str, Any] = {"type": "object", "properties": {}}
    # Collect all keys from all records
    key_types: dict[str, set[str]] = {}
    for r in records:
        for k, v in r.data.items():
            key_types.setdefault(k, set())
            if isinstance(v, str):
                key_types[k].add("string")
            elif isinstance(v, (int, float)):
                key_types[k].add("number")
            elif isinstance(v, bool):
                key_types[k].add("boolean")
            elif isinstance(v, list):
                key_types[k].add("array")
            elif isinstance(v, dict):
                key_types[k].add("object")
            else:
                key_types[k].add("null")
    # Merge
    for k, types in key_types.items():
        if len(types) == 1:
            schema["properties"][k] = {"type": list(types)[0]}
        else:
            schema["properties"][k] = {"type": list(types)}
    return schema


def _validates(f: Callable[..., T]) -> Callable[..., T]:
    f._is_validator = True  # type: ignore[attr-defined]
    return f


def validate_fields(required_fields: set[str]) -> Validator:
    @_validates
    def validator(record: Record) -> bool:
        return required_fields.issubset(record.data.keys())
    return validator


def validate_range(field: str, min_val: int | None = None, max_val: int | None = None) -> Validator:
    @_validates
    def validator(record: Record) -> bool:
        val = record.data.get(field)
        if val is None:
            return True
        try:
            num = float(val)
            if min_val is not None and num < min_val:
                return False
            if max_val is not None and num > max_val:
                return False
            return True
        except Exception:
            return False
    return validator


def validate_regex(field: str, pattern: str) -> Validator:
    import re

    regex = re.compile(pattern)
    @_validates
    def validator(record: Record) -> bool:
        val = record.data.get(field)
        if val is None:
            return True
        return regex.search(str(val)) is not None
    return validator


def validate(record: Record, validators: list[Validator]) -> bool:
    return all(v(record) for v in validators)
