class DbSource:
    def __init__(self, table: str, query: str | None = None) -> None:
        self.table = table
        self.query = query

    def get_table_row_count(self) -> int:
        return get_table_row_count(self.table)

    def read_table(self) -> list[Record]:
        rows = execute_query(f"SELECT * FROM {self.table}")
        return [_row_to_record(r) for r in rows]

    def iter_records(self) -> Iterator[Record]:
        if self.query:
            rows = execute_query(self.query)
        else:
            rows = execute_query(f"SELECT * FROM {self.table}")
        for r in rows:
            yield _row_to_record(r)

    def execute_query(self, query: str) -> list[Record]:
        rows = execute_query(query)
        return [_row_to_record(r) for r in rows]


def ingest_from_tables(tables: list[str], batch_size: int = 1000, metrics: Any = None) -> Iterator[Record]:
    for table in tables:
        try:
            db_source = DbSource(table=table)
            for rec in db_source.iter_records():
                yield rec  # caller tracks metrics
                if metrics:
                    metrics.counter("db_records_read").inc()
        except Exception as e:
            if metrics:
                metrics.counter("db_read_failures").inc()
            # Log error, continue with next table
            print(f"Failed to read table {table}: {e}")
